    private function do_watch_order_book(string $symbol, ?int $limit = null, $params = array()) {
        /**
         *
         * @see https://docs.derive.xyz/api-reference/channels/orderbook
         *
         * watches information on open orders with bid (buy) and ask (sell) prices, volumes and other data
         * @param {string} $symbol unified $symbol of the $market to fetch the order book for
         * @param {int} [$limit] the maximum amount of order book entries to return.
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} an ~@link https://docs.ccxt.com/?id=order-book-structure order book structure~
         */
        if ($this->markets === null) {
            Async\await($this->load_markets());
        }
        $limitResolved = ($limit === null) ? 10 : $limit;
        $market = $this->market($symbol);
        $marketId = $this->safe_string($market, 'id', '');
        $topic = 'orderbook.' . $marketId . '.10.' . $this->number_to_string($limitResolved);
        $request = array(
            'method' => 'subscribe',
            'params' => array(
                'channels' => array(
                    $topic,
                ),
            ),
        );
        $subscription = array(
            'name' => $topic,
            'symbol' => $symbol,
            'limit' => $limitResolved,
            'params' => $params,
        );
        $orderbook = Async\await($this->watch_public($topic, $request, $subscription));
        return $orderbook->limit();
    }

    public function handle_order_book(Client $client, array $message) {
        //
        // {
        //     method: 'subscription',
        //     params: {
        //       channel: 'orderbook.BTC-PERP.10.1',
        //       data: {
        //         timestamp: 1738331231506,
        //         instrument_name: 'BTC-PERP',
        //         publish_id: 628419,
        //         bids: [ [ '104669', '40' ] ],
        //         asks: [ [ '104736', '40' ] ]
        //       }
        //     }
        // }
        //
        $params = $this->safe_dict($message, 'params');
        $data = $this->safe_dict($params, 'data', array());
        $marketId = $this->safe_string($data, 'instrument_name');
        $market = $this->safe_market($marketId);
        $symbol = $this->safe_string($market, 'symbol', '');
        $topic = $this->safe_string($params, 'channel');
        if (!(is_array($this->orderbooks) && array_key_exists($symbol ?? '', $this->orderbooks))) {
            $defaultLimit = $this->safe_integer($this->options, 'watchOrderBookLimit', 1000);
            $subscription = ($topic === null) ? null : $client->subscriptions[$topic];
            $limit = $this->safe_integer($subscription, 'limit', $defaultLimit);
            $this->orderbooks[$symbol] = $this->order_book(array(), $limit);
        }
        $orderbook = $this->orderbooks[$symbol];
        $timestamp = $this->safe_integer($data, 'timestamp');
        $snapshot = $this->parse_order_book($data, $symbol, $timestamp, 'bids', 'asks');
        $orderbook->reset($snapshot);
        $client->resolve($orderbook, $topic);
    }

