    private function do_watch_ticker(string $symbol, $params = array()) {
        /**
         *
         * @see https://docs.derive.xyz/api-reference/channels/tickerslim
         *
         * watches a price ticker, a statistical calculation with the information calculated over the past 24 hours for a specific $market
         * @param {string} $symbol unified $symbol of the $market to fetch the ticker for
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a ~@link https://docs.ccxt.com/?id=ticker-structure ticker structure~
         */
        if ($this->markets === null) {
            Async\await($this->load_markets());
        }
        $market = $this->market($symbol);
        $marketId = $this->safe_string($market, 'id', '');
        $topic = 'ticker_slim.' . $marketId . '.100'; // v3 removed the fat ticker channel, ticker_slim is the only ticker feed
        $request = array(
            'method' => 'subscribe',
            'params' => array(
                'channels' => array(
                    $topic,
                ),
            ),
        );
        $subscription = array(
            'name' => $topic,
            'symbol' => $symbol,
            'params' => $params,
        );
        return Async\await($this->watch_public($topic, $request, $subscription));
    }

